 @Test public void hostOnlyCallbacksUseEffectiveNativeEditorInfo()throws Exception{
  select();NativeQuickBridge.finish(service);
  for(boolean viewCallback:new boolean[]{false,true}){
   service.externalInfo=null;service.internalInfo=info(1,0x01000000);
   if(viewCallback)NativeQuickBridge.viewStarted(service);else NativeQuickBridge.start(service);
   assertTrue("Host-only callback initializes from internal metadata",NativeQuickBridge.active());
   assertSame(service.internalConnection,get("connection"));assertTrue(engine().isPrivateMode());
   type("enym");choose("測試");assertEquals(0,engine().learnedEntryCount());
   service.externalInfo=info(1,0);service.internalInfo=info(1|0x80,0);
   if(viewCallback)NativeQuickBridge.viewStarted(service);else NativeQuickBridge.start(service);
   assertFalse("Effective password policy overrides permissive external info",NativeQuickBridge.active());assertFalse(key('e'));assertTrue(engine().isPrivateMode());
   service.internalInfo=null;
   if(viewCallback)NativeQuickBridge.viewStarted(service);else NativeQuickBridge.start(service);
   assertFalse("Missing effective info fails closed",NativeQuickBridge.active());assertFalse(key('e'));
   service.externalInfo=info(1|0x80,0);service.internalInfo=info(1,0);
   if(viewCallback)NativeQuickBridge.viewStarted(service);else NativeQuickBridge.start(service);
   assertTrue("Effective ordinary policy overrides protected external info",NativeQuickBridge.active());assertFalse(engine().isPrivateMode());
   type("enym");assertEquals("水弓'卜一",NativeQuickBridge.pendingText());NativeQuickBridge.finish(service);
  }
  assertEquals("測試測試",edit.getText().toString());assertEquals(0,engine().learnedEntryCount());assertEquals(0,sampled);
 }
